'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),crypto=require('node:crypto'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const profile=require('../../../collectors/nodered/live-integration/live-profile');
function fixture(){const m={arch_trees:{},capture:{method:'POST',node:'in',url:'/run'},env:{},export_endpoint:'https://causal-ingress:8443/v1/causal-events',files:{},flow_sha256:'88'.repeat(32),image:'docker.io/nodered/node-red:5.0.9@sha256:e085d4a06591fd0aca2ea2a91364d27f1a0e31e885675f77935e10f95412a963',mounts:{ca:'/run/apicontour/live/ca.pem',export_cert:'/run/apicontour/live/export.pem',export_key:'/run/apicontour/live/export.key',product_cert:'/run/apicontour/live/product.pem',product_key:'/run/apicontour/live/product.key',server_cert:'/run/apicontour/live/server.pem',server_key:'/run/apicontour/live/server.key'},node:'24.22.1',nodes:[['in','http in'],['request','http request']],product_endpoint:'https://pilot-gateway:9443/pilot',profile_id:'00000000-0000-4000-8000-000000000503',profile_name:'nodered_5_0_9_wire_v1',version:1};return m;}
function check(m,descriptor={}){const bytes=Buffer.from(JSON.stringify(m));return profile.validateManifest(bytes,{profile_id:m.profile_id,manifest_sha256:crypto.createHash('sha256').update(bytes).digest('hex'),...descriptor});}
test('closed manifest rejects mount, profile, source and endpoint policy drift',()=>{const m=fixture();assert.equal(check(m).profile_id,m.profile_id);for(const mutate of [x=>x.mounts.ca='/tmp/untrusted',x=>x.profile_id='00000000-0000-4000-8000-000000000501',x=>x.export_endpoint='http://export.test/v1/causal-events',x=>x.product_endpoint='https://product.test/?x=1',x=>x.nodes.push(['in','function']),x=>x.capture.url='/other']){const x=structuredClone(m);mutate(x);assert.throws(()=>check(x));}assert.throws(()=>check(m,{manifest_sha256:'00'.repeat(32)}));});
test('secure regular reads refuse symlinks, hardlinks and unsafe key modes',()=>{const dir=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'live-profile-')));try{const file=path.join(dir,'key'),link=path.join(dir,'link'),hard=path.join(dir,'hard');fs.writeFileSync(file,'synthetic',{mode:0o600});assert.equal(profile.read(file,20,true).toString(),'synthetic');fs.chmodSync(file,0o644);assert.throws(()=>profile.read(file,20,true));fs.chmodSync(file,0o600);fs.symlinkSync(file,link);assert.throws(()=>profile.read(link,20,true));const nested=path.join(dir,'nested');fs.mkdirSync(nested);const nestedKey=path.join(nested,'key');fs.writeFileSync(nestedKey,'synthetic',{mode:0o600});const alias=path.join(dir,'alias');fs.symlinkSync(nested,alias);assert.throws(()=>profile.read(path.join(alias,'key'),20,true));fs.linkSync(file,hard);assert.throws(()=>profile.read(file,20,true));}finally{fs.rmSync(dir,{recursive:true,force:true});}});

test('file growth is detected with a bounded read',t=>{const dir=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'live-growth-')));try{const file=path.join(dir,'file');fs.writeFileSync(file,'start');const original=fs.readSync;let once=false,max=0;t.mock.method(fs,'readSync',function(fd,buffer,offset,length,position){max=Math.max(max,buffer.length);if(!once){once=true;fs.appendFileSync(file,'-growth');}return original(fd,buffer,offset,length,position);});assert.throws(()=>profile.read(file,8));assert.equal(max,6);}finally{fs.rmSync(dir,{recursive:true,force:true});}});
test('bounded exact tree refuses extra directories, link drift and missing files',()=>{const root=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'live-tree-')));try{fs.writeFileSync(path.join(root,'a'),'hello');fs.mkdirSync(path.join(root,'sub'));fs.writeFileSync(path.join(root,'sub','b'),'bye');fs.symlinkSync('a',path.join(root,'alias'));const h=x=>crypto.createHash('sha256').update(x).digest('hex');const m={node:'24.22.1',root,file_count:2,total_bytes:8,files:{a:{bytes:5,sha256:h('hello')},'sub/b':{bytes:3,sha256:h('bye')}},symlinks:{alias:'a'}},limits={files:2,bytes:8,links:1};assert.equal(profile.validateTree(root,m,limits),true);fs.mkdirSync(path.join(root,'unexpected'));assert.throws(()=>profile.validateTree(root,m,limits));fs.rmdirSync(path.join(root,'unexpected'));fs.unlinkSync(path.join(root,'alias'));fs.symlinkSync('sub/b',path.join(root,'alias'));assert.throws(()=>profile.validateTree(root,m,limits));fs.unlinkSync(path.join(root,'alias'));fs.symlinkSync('a',path.join(root,'alias'));fs.unlinkSync(path.join(root,'sub','b'));assert.throws(()=>profile.validateTree(root,m,limits));}finally{fs.rmSync(root,{recursive:true,force:true});}});
test('tree hash reads are bounded and reject growth',t=>{const root=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'live-tree-grow-')));try{const file=path.join(root,'file');fs.writeFileSync(file,'start');const m={node:'24.22.1',root,file_count:1,total_bytes:5,files:{file:{bytes:5,sha256:crypto.createHash('sha256').update('start').digest('hex')}},symlinks:{}},original=fs.readSync;let once=false,largest=0;t.mock.method(fs,'readSync',function(fd,buffer,offset,length,position){largest=Math.max(largest,buffer.length);if(!once){once=true;fs.appendFileSync(file,'-growth');}return original(fd,buffer,offset,length,position);});assert.throws(()=>profile.validateTree(root,m,{files:1,bytes:5,links:0}));assert.equal(largest,65536);}finally{fs.rmSync(root,{recursive:true,force:true});}});
